3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the {@code customerCode} to the freshly built {@link Owner} before it is saved.
9	 *
10	 * <p>The code is formatted {@code '<LAST3>-<NNNN>'}: LAST3 is the upper-cased first three
11	 * letters of the owner's last name, and NNNN is a global 4-digit zero-padded sequence equal
12	 * to one more than the current number of owners (e.g. {@code 'SMI-0007'}). Running before
13	 * {@link SaveOwner} means the new owner is not yet counted, so the sequence increments by one
14	 * per created owner.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String lastName = owner.getLastName();
20	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
21	        int sequence = ownerRepository.findAll().size() + 1;
22	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
23	    }
24	}
